#include <algorithm>
#include <iostream>
#include <queue>
#include <string>
#include <tuple>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int R, C;
    cin >> R >> C;
    vector<string> g(R);
    for (auto &row : g) cin >> row;
    const int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
    vector<vector<int>> d(R, vector<int>(C, -1));
    queue<pair<int, int>> q;
    int sr = 0, sc = 0, er = 0, ec = 0;
    for (int r = 0; r < R; r++)
        for (int c = 0; c < C; c++) {
            if (g[r][c] == '*') {
                d[r][c] = 0;
                q.push({r, c});
            } else if (g[r][c] == 'S') {
                sr = r, sc = c;
            } else if (g[r][c] == 'E') {
                er = r, ec = c;
            }
        }
    // Multi-source BFS: distance from every cell to the nearest obstacle.
    while (!q.empty()) {
        auto [r, c] = q.front();
        q.pop();
        for (int k = 0; k < 4; k++) {
            int x = r + dr[k], y = c + dc[k];
            if (x >= 0 && x < R && y >= 0 && y < C && d[x][y] < 0) {
                d[x][y] = d[r][c] + 1;
                q.push({x, y});
            }
        }
    }
    // Widest path: always expand the state with the largest bottleneck first.
    vector<vector<int>> best(R, vector<int>(C, -1));
    best[sr][sc] = d[sr][sc];
    priority_queue<tuple<int, int, int>> h;
    h.push({best[sr][sc], sr, sc});
    while (!h.empty()) {
        auto [v, r, c] = h.top();
        h.pop();
        if (v < best[r][c]) continue;
        if (r == er && c == ec) {
            cout << v << '\n';
            return 0;
        }
        for (int k = 0; k < 4; k++) {
            int x = r + dr[k], y = c + dc[k];
            if (x >= 0 && x < R && y >= 0 && y < C) {
                int nv = min(v, d[x][y]);
                if (nv > best[x][y]) {
                    best[x][y] = nv;
                    h.push({nv, x, y});
                }
            }
        }
    }
    cout << -1 << '\n';
}

import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int R = (int) nextLong(), C = (int) nextLong();
        char[][] g = new char[R][];
        for (int r = 0; r < R; r++) g[r] = next().toCharArray();
        int[] dr = {1, -1, 0, 0}, dc = {0, 0, 1, -1};
        int[][] d = new int[R][C];
        int[] queue = new int[R * C];
        int qh = 0, qt = 0, start = 0, end = 0;
        for (int r = 0; r < R; r++)
            for (int c = 0; c < C; c++) {
                d[r][c] = -1;
                if (g[r][c] == '*') {
                    d[r][c] = 0;
                    queue[qt++] = r * C + c;
                } else if (g[r][c] == 'S') {
                    start = r * C + c;
                } else if (g[r][c] == 'E') {
                    end = r * C + c;
                }
            }
        // Multi-source BFS: distance from every cell to the nearest obstacle.
        while (qh < qt) {
            int r = queue[qh] / C, c = queue[qh] % C;
            qh++;
            for (int k = 0; k < 4; k++) {
                int x = r + dr[k], y = c + dc[k];
                if (x >= 0 && x < R && y >= 0 && y < C && d[x][y] < 0) {
                    d[x][y] = d[r][c] + 1;
                    queue[qt++] = x * C + y;
                }
            }
        }
        // Widest path: always expand the state with the largest bottleneck first.
        int[][] best = new int[R][C];
        for (int[] row : best) Arrays.fill(row, -1);
        int sr = start / C, sc = start % C;
        best[sr][sc] = d[sr][sc];
        PriorityQueue<int[]> h = new PriorityQueue<>((a, b) -> Integer.compare(b[0], a[0]));
        h.add(new int[] {best[sr][sc], sr, sc});
        while (!h.isEmpty()) {
            int[] top = h.poll();
            int v = top[0], r = top[1], c = top[2];
            if (v < best[r][c]) continue;
            if (r * C + c == end) {
                System.out.println(v);
                return;
            }
            for (int k = 0; k < 4; k++) {
                int x = r + dr[k], y = c + dc[k];
                if (x >= 0 && x < R && y >= 0 && y < C) {
                    int nv = Math.min(v, d[x][y]);
                    if (nv > best[x][y]) {
                        best[x][y] = nv;
                        h.add(new int[] {nv, x, y});
                    }
                }
            }
        }
        System.out.println(-1);
    }
}

package main

import (
	"container/heap"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

type state struct{ v, cell int }
type maxHeap []state

func (h maxHeap) Len() int           { return len(h) }
func (h maxHeap) Less(i, j int) bool { return h[i].v > h[j].v }
func (h maxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *maxHeap) Push(x any)        { *h = append(*h, x.(state)) }
func (h *maxHeap) Pop() any {
	old := *h
	x := old[len(old)-1]
	*h = old[:len(old)-1]
	return x
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	R, C := int(nextInt()), int(nextInt())
	g := make([]string, R)
	for r := range g {
		g[r] = nextToken()
	}
	dr, dc := [4]int{1, -1, 0, 0}, [4]int{0, 0, 1, -1}
	d := make([]int, R*C)
	queue := make([]int, 0, R*C)
	start, end := 0, 0
	for r := 0; r < R; r++ {
		for c := 0; c < C; c++ {
			d[r*C+c] = -1
			switch g[r][c] {
			case '*':
				d[r*C+c] = 0
				queue = append(queue, r*C+c)
			case 'S':
				start = r*C + c
			case 'E':
				end = r*C + c
			}
		}
	}
	// Multi-source BFS: distance from every cell to the nearest obstacle.
	for qh := 0; qh < len(queue); qh++ {
		r, c := queue[qh]/C, queue[qh]%C
		for k := 0; k < 4; k++ {
			x, y := r+dr[k], c+dc[k]
			if x >= 0 && x < R && y >= 0 && y < C && d[x*C+y] < 0 {
				d[x*C+y] = d[r*C+c] + 1
				queue = append(queue, x*C+y)
			}
		}
	}
	// Widest path: always expand the state with the largest bottleneck first.
	best := make([]int, R*C)
	for i := range best {
		best[i] = -1
	}
	best[start] = d[start]
	h := &maxHeap{{d[start], start}}
	for h.Len() > 0 {
		top := heap.Pop(h).(state)
		if top.v < best[top.cell] {
			continue
		}
		if top.cell == end {
			fmt.Println(top.v)
			return
		}
		r, c := top.cell/C, top.cell%C
		for k := 0; k < 4; k++ {
			x, y := r+dr[k], c+dc[k]
			if x >= 0 && x < R && y >= 0 && y < C {
				nv := min(top.v, d[x*C+y])
				if nv > best[x*C+y] {
					best[x*C+y] = nv
					heap.Push(h, state{nv, x*C + y})
				}
			}
		}
	}
	fmt.Println(-1)
}
